/// <summary>
/// Extension of HMCWorker table
/// </summary>
[ExtensionOf(tableStr(HcmWorker))]
final class NDXHcmWorker_tbl_Extension
{
}

Method.Source:
/// <summary>
/// find DimensionAttributeValueSet for worker
/// </summary>
/// <returns>DimensionAttributeValueSet record</returns>
public DimensionAttributeValueSet findDimensionAttributeValueSet()
{
    DimensionAttributeValueSet lDimensionAttributeValueSet;
    HcmEmployment lHcmEmployment;
    CompanyInfo lCompanyInfo;

    select lDimensionAttributeValueSet
        join lHcmEmployment
            where lHcmEmployment.DefaultDimension == lDimensionAttributeValueSet.RecId
                && lHcmEmployment.Worker == this.RecId
        join lCompanyInfo
            where lCompanyInfo.RecId == lHcmEmployment.LegalEntity;

    return lDimensionAttributeValueSet;
}
